#include <stdio.h>
#include <string.h>
#include <stdlib.h>

static int matches(char open, char close)
{
    return (open == '(' && close == ')') ||
           (open == '[' && close == ']') ||
           (open == '{' && close == '}');
}

static int is_balanced(const char *s)
{
    size_t len = strlen(s);
    char *stack = (char *)malloc(len);
    size_t top = 0;
    int ok = 1;
    for (size_t i = 0; i < len && ok; ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            stack[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0) { ok = 0; break; }
            char open = stack[--top];
            if (!matches(open, c)) { ok = 0; break; }
        }
    }
    if (ok && top == 0) ok = 1; else ok = 0;
    free(stack);
    return ok;
}

int main(int argc, char *argv[])
{
    const char *input = (argc >= 2) ? argv[1] : "";
    if (is_balanced(input))
        puts("BALANCED");
    else
        puts("UNBALANCED");
    return 0;
}
